PRAGMA foreign_keys=ON;
CREATE TABLE schema_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL) STRICT;
CREATE TABLE ingest_runs(record_id TEXT PRIMARY KEY,recorded_at TEXT NOT NULL,input_sha256 TEXT NOT NULL) STRICT;
CREATE TABLE source_files(source_id TEXT PRIMARY KEY,path TEXT NOT NULL,sha256 TEXT NOT NULL CHECK(length(sha256)=64),size_bytes INTEGER NOT NULL CHECK(size_bytes>=0),record_id TEXT NOT NULL REFERENCES ingest_runs) STRICT;
CREATE TABLE asset_registry(asset_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES source_files,uri TEXT NOT NULL,retention TEXT NOT NULL,verification_status TEXT NOT NULL) STRICT;
CREATE TABLE data_dictionary(object_name TEXT NOT NULL,column_name TEXT NOT NULL,data_type TEXT NOT NULL,unit TEXT,description TEXT NOT NULL,PRIMARY KEY(object_name,column_name)) STRICT;
CREATE TABLE query_catalog(query_id TEXT PRIMARY KEY,sql_text TEXT NOT NULL,expected_columns_json TEXT NOT NULL,interpretation_boundary TEXT NOT NULL) STRICT;
CREATE TABLE stages(stage_id TEXT PRIMARY KEY,ordinal INTEGER UNIQUE NOT NULL,title TEXT NOT NULL,acceptance TEXT NOT NULL) STRICT;
CREATE TABLE stage_events(event_id TEXT PRIMARY KEY,sequence INTEGER NOT NULL UNIQUE,stage_id TEXT NOT NULL REFERENCES stages,status TEXT NOT NULL CHECK(status IN ('planned','blocked','active','complete','optional')),acceptance_scope TEXT NOT NULL CHECK(acceptance_scope IN ('design','scientific','none')),source_id TEXT NOT NULL REFERENCES source_files,note TEXT NOT NULL,record_id TEXT NOT NULL REFERENCES ingest_runs) STRICT;
CREATE TABLE decisions(decision_id TEXT PRIMARY KEY,stage_id TEXT NOT NULL REFERENCES stages,question TEXT NOT NULL,proposed_owner TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('proposed','accepted','rejected','resolved')),recommendation TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES source_files,record_id TEXT NOT NULL REFERENCES ingest_runs) STRICT;
CREATE TABLE reviews(review_id TEXT PRIMARY KEY,stage_id TEXT NOT NULL REFERENCES stages,reviewer TEXT NOT NULL,reviewer_kind TEXT NOT NULL CHECK(reviewer_kind IN ('agent','human')),status TEXT NOT NULL CHECK(status IN ('pending','pass','fail')),source_id TEXT NOT NULL REFERENCES source_files,scope TEXT NOT NULL,record_id TEXT NOT NULL REFERENCES ingest_runs) STRICT;
CREATE TABLE result_sets(result_id TEXT PRIMARY KEY,stage_id TEXT NOT NULL REFERENCES stages,scope TEXT NOT NULL CHECK(scope IN ('historical_context','new_study')),state TEXT NOT NULL CHECK(state IN ('planned','complete','failed')),evidence_tier TEXT NOT NULL CHECK(evidence_tier IN ('observed_prediction','observed_physical','engineering','analytical','synthetic','planned')),source_id TEXT NOT NULL REFERENCES source_files,independent_unit TEXT NOT NULL,conditions_json TEXT NOT NULL,interpretation_boundary TEXT NOT NULL,review_state TEXT NOT NULL CHECK(review_state IN ('unreviewed','agent_checked','human_reviewed')),supersedes TEXT REFERENCES result_sets,record_id TEXT NOT NULL REFERENCES ingest_runs) STRICT;
CREATE TABLE observations(observation_id TEXT PRIMARY KEY,result_id TEXT NOT NULL REFERENCES result_sets,metric TEXT NOT NULL,unit TEXT NOT NULL,value REAL,missing_reason TEXT,independent_n INTEGER CHECK(independent_n>0),replicate_id TEXT,ci_low REAL,ci_high REAL,CHECK((value IS NOT NULL AND missing_reason IS NULL) OR (value IS NULL AND missing_reason IS NOT NULL)),CHECK((ci_low IS NULL AND ci_high IS NULL) OR (ci_low IS NOT NULL AND ci_high IS NOT NULL AND ci_low<=ci_high))) STRICT;
CREATE VIEW stage_overview AS SELECT s.stage_id,s.ordinal,s.title,e.status,e.acceptance_scope,e.note,e.source_id FROM stages s JOIN stage_events e ON e.stage_id=s.stage_id WHERE e.sequence=(SELECT max(x.sequence) FROM stage_events x WHERE x.stage_id=s.stage_id);
